(()=>{'use strict';
const M=window.PlannerModel,KEY='brooks-daily-planner-v2',OLD='brooks-reset-planner-v1',root=document.getElementById('daily-app');
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const today=()=>{let d=new Date();return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`};
let selected=today(),state=M.empty(),blocked=false,dirty=false,savedRaw=null,tab='daily',notice='Entries save on this device.';
try{savedRaw=localStorage.getItem(KEY);if(savedRaw!==null)state=M.validate(JSON.parse(savedRaw));}catch{blocked=true;notice='Saved data could not be read. Automatic saving is stopped to protect it. Export a backup before continuing.';}
function save(){dirty=true;if(blocked){message(notice);return false}try{
 if(localStorage.getItem(KEY)!==savedRaw)throw Error('Your planner changed in another tab. Export this tab’s data, then reload before editing.');
 const raw=JSON.stringify(M.validate(state));localStorage.setItem(KEY,raw);savedRaw=raw;dirty=false;notice='Saved on this device.';message(notice);return true;
 }catch(error){notice=error.message.includes('another tab')||error.message.includes('Invalid')?error.message:'Unable to save. Keep this page open and export a backup now.';message(notice);return false}}
window.addEventListener('storage',e=>{if(e.key===KEY||e.key===null){notice='Your planner changed in another tab. Export this tab’s data, then reload before editing.';message(notice)}});
window.addEventListener('beforeunload',e=>{if(dirty){e.preventDefault();e.returnValue=''}});
function message(t){document.getElementById('daily-status').textContent=t}
const button=(label,action,cls='secondary')=>`<button class="${cls}" data-action="${action}">${label}</button>`;
const field=(label,key)=>`<div class="field"><label for="daily-${key}">${label}</label><textarea id="daily-${key}" data-daily="${key}">${esc(state.days[selected]?.[key]||'')}</textarea></div>`;
function render(){
 document.getElementById('legacy-reset').hidden=!state.showReset;
 root.innerHTML=`<nav class="mode-nav" aria-label="Planner sections">${[['daily','Daily planner'],['challenges','Challenges'],['history','History & backups']].map(([id,label])=>`<button data-tab="${id}" ${tab===id?'aria-current="page" class="active"':''}>${label}</button>`).join('')}</nav><section class="card"><div id="daily-content"></div><p id="daily-status" role="status" aria-live="polite">${esc(notice)}</p></section>`;
 const p=document.getElementById('daily-content');
 if(tab==='daily')p.innerHTML=`<div class="eyebrow">A fresh page, every day</div><h2>Your daily planner</h2><p class="intro">Keep a plan for any date. Challenges are always optional.</p><div class="date-row">${button('Previous day','previous')}<label for="plan-date">Planning date<input type="date" id="plan-date" value="${selected}"></label>${button('Next day','tomorrow')}${button('Today','today')}</div>${field('My priorities','priorities')}${field('Schedule & notes','schedule')}${field('Reflection','reflection')}<div class="actions">${button('Print this day / Save PDF','print')}<label class="habit"><input type="checkbox" id="reset-toggle" ${state.showReset?'checked':''}>Show original seven-day worksheets</label></div><p class="notice">Turning the worksheets off keeps every answer. Use Challenges to start a new guided reset with its own progress history.</p>`;
 if(tab==='challenges')p.innerHTML=`<div class="eyebrow">Your pace. Your goals.</div><h2>Optional challenges</h2><p class="intro">Start a guided seven-day reset or create your own. Days advance when you choose; pausing keeps all progress.</p>${button('Start a guided 7-day reset','guided','primary')}<details class="challenge-create"><summary>Create a custom challenge</summary><form id="challenge-form"><label for="challenge-name">Challenge name</label><input id="challenge-name" name="name" type="text" required maxlength="120"><label for="challenge-goal">My goal</label><textarea id="challenge-goal" name="goal" maxlength="2000"></textarea><label for="challenge-duration">Number of days (1–365)</label><input id="challenge-duration" name="duration" type="number" min="1" max="365" value="7" required><label for="challenge-tasks">Daily activities — one per line (up to 20)</label><textarea id="challenge-tasks" name="tasks" required placeholder="Read for ten minutes&#10;Take a short walk"></textarea><button class="primary" type="submit">Create challenge</button></form></details><div id="challenge-list">${state.challenges.filter(c=>c.status!=='completed').map(card).join('')||'<p>No active challenges. Your daily planner is ready whenever you are.</p>'}</div>`;
 if(tab==='history')p.innerHTML=`<div class="eyebrow">Keep what matters</div><h2>History & backups</h2><p class="intro">Data stays in this browser. Export regularly: clearing browser data can remove your entries. No account or cloud sync is included.</p><div class="actions">${button('Export all planner data','export','primary')}<label class="secondary" for="import-backup">Import backup<input id="import-backup" type="file" accept="application/json,.json"></label></div><p class="notice">Import adds missing dates and challenges. Existing dates, matching challenges, and original worksheet answers stay unchanged. The page reloads after import. Original reset worksheets are included in backups.</p><h3>Saved days</h3><div class="saved-days">${Object.keys(state.days).sort().reverse().map(d=>`<button class="secondary" data-date="${d}">${d}</button>`).join('')||'<p>Your saved daily entries will appear here.</p>'}</div><h3>Challenge history</h3>${state.challenges.map(card).join('')||'<p>No challenges yet.</p>'}`;
}
function card(c){const completed=Object.values(c.checks).filter(Boolean).length,total=c.duration*c.tasks.length;return `<article class="challenge-card" data-challenge="${esc(c.id)}"><h3>${esc(c.name)}</h3><p>${esc(c.goal)}</p><p>${esc(c.status)} · Day ${c.day} of ${c.duration} · Started ${c.started}</p><label>Activities recorded: ${completed} / ${total}<progress max="${total}" value="${completed}"></progress></label>${c.kind==='guided'?`<p><strong data-theme>${esc(M.themes[c.day-1])}</strong></p>`:''}<label for="day-${c.id}">Review challenge day</label><select id="day-${c.id}" data-review="${c.id}">${Array.from({length:c.duration},(_,i)=>`<option value="${i+1}" ${i+1===c.day?'selected':''}>Day ${i+1}</option>`).join('')}</select><div class="task-list">${tasks(c,c.day)}</div><div class="actions">${c.status==='active'?button('Pause','pause')+(c.day<c.duration?button('Advance to next day','next'):button('Finish & keep history','complete','primary')):c.status==='paused'?button('Resume','resume','primary'):'<span>Completed — history preserved.</span>'}</div></article>`}
function tasks(c,d){return c.tasks.map((t,i)=>`<label class="habit"><input type="checkbox" data-check="${d}:${i}" ${c.checks[`${d}:${i}`]?'checked':''} ${c.status!=='active'?'disabled':''}>${esc(t)}</label>`).join('')}
root.addEventListener('input',e=>{if(e.target.dataset.daily){const k=e.target.dataset.daily;(state.days[selected]??={})[k]=e.target.value;save()}});
root.addEventListener('change',async e=>{
 if(e.target.id==='plan-date'&&M.date(e.target.value)){selected=e.target.value;render()}
 if(e.target.id==='reset-toggle'){state.showReset=e.target.checked;save();document.getElementById('legacy-reset').hidden=!state.showReset}
 const cardEl=e.target.closest('[data-challenge]'),c=state.challenges.find(c=>c.id===cardEl?.dataset.challenge);
 if(e.target.dataset.check&&c?.status==='active'){c.checks[e.target.dataset.check]=e.target.checked;save();const count=Object.values(c.checks).filter(Boolean).length;cardEl.querySelector('progress').value=count;cardEl.querySelector('progress').parentElement.firstChild.textContent=`Activities recorded: ${count} / ${c.duration*c.tasks.length}`;}
 if(e.target.dataset.review&&c){cardEl.querySelector('.task-list').innerHTML=tasks(c,Number(e.target.value));if(c.kind==='guided')cardEl.querySelector('[data-theme]').textContent=M.themes[Number(e.target.value)-1]}
 if(e.target.id==='import-backup'&&e.target.files[0]){try{const file=e.target.files[0];if(file.size>10000000)throw Error('Backup must be smaller than 10 MB.');const data=JSON.parse(await file.text());if(data.format!=='brooks-planner-backup'||!data.planner)throw Error('Choose an exported planner backup.');if(blocked)throw Error('Current saved data needs recovery before importing.');const merged=M.merge(state,data.planner);const legacy=M.mergeLegacy(localStorage.getItem(OLD),data.legacyResetRaw);state=merged;if(save()){localStorage.setItem(OLD,legacy);window.location.reload();}}catch(err){message(err.message)}}
});
root.addEventListener('submit',e=>{if(e.target.id!=='challenge-form')return;e.preventDefault();const form=new FormData(e.target);try{add({name:form.get('name'),goal:form.get('goal'),duration:Number(form.get('duration')),tasks:form.get('tasks').split('\n'),kind:'custom'});}catch(err){message(err.message)}});
function add(config){M.create(state,{...config,id:'c'+(crypto.randomUUID?crypto.randomUUID():Array.from(crypto.getRandomValues(new Uint32Array(4))).map(n=>n.toString(16)).join('-')),started:today()});save();render();}
root.addEventListener('click',e=>{
 const b=e.target.closest('button');if(!b)return;if(b.dataset.tab){tab=b.dataset.tab;render();return}if(b.dataset.date){selected=b.dataset.date;tab='daily';render();return}
 const a=b.dataset.action,c=state.challenges.find(c=>c.id===b.closest('[data-challenge]')?.dataset.challenge);
 if(c){M.transition(c,a);save();render();return}
 if(a==='guided')add({name:'7-Day Reset',goal:'One small step each day.',duration:7,tasks:['Take one small action for today’s theme','Make time to pause','Write a reflection in my daily planner'],kind:'guided'});
 if(a==='today'){selected=today();render()}
 if(a==='previous'||a==='tomorrow'){const d=new Date(selected+'T12:00:00');d.setDate(d.getDate()+(a==='previous'?-1:1));selected=`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;render()}
 if(a==='print'){document.body.classList.add('print-daily');window.print();document.body.classList.remove('print-daily')}
 if(a==='export'){let legacy=null,unreadable=null;try{legacy=localStorage.getItem(OLD);if(blocked)unreadable=localStorage.getItem(KEY)}catch{}const file=new Blob([JSON.stringify({format:'brooks-planner-backup',exportedAt:new Date().toISOString(),planner:state,legacyResetRaw:legacy,unreadableSavedData:unreadable},null,2)],{type:'application/json'}),url=URL.createObjectURL(file),link=document.createElement('a');link.href=url;link.download=`planner-backup-${today()}.json`;link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);message('Backup download requested. Keep the file somewhere safe.');}
});
window.addEventListener('beforeprint',()=>{document.querySelectorAll('textarea').forEach(t=>{const p=document.createElement('div');p.className='print-copy';p.textContent=t.value;t.after(p)})});
window.addEventListener('afterprint',()=>document.querySelectorAll('.print-copy').forEach(p=>p.remove()));
render();
})();
